Contract LoanProcessingSystemSystem::closeOutLoan(loanid:Integer): Boolean {

            precondition:
          loan:Loan = Loan.allInstance()->any(o | o.LoanID = loanid) and loan.oclIsTypeOf(Loan) and loan.Status = LoanStatus::LSOPEN

            postcondition:
          loan.Status = LoanStatus::CLOSED and result = true

        }
